export function evaluate({ inputs, time, seed, state }) {
  const launchSpeed = inputs.launchSpeed;
  const gravity = inputs.gravity;
  const apexTime = launchSpeed / gravity;
  const apexHeight = (launchSpeed * launchSpeed) / (2 * gravity);

  const t = time;
  const tossVelocity = launchSpeed - gravity * t;
  const tossHeight = launchSpeed * t - (gravity * t * t) / 2;
  const tossAcceleration = -gravity;

  const isReleased = t >= apexTime;
  const dropTime = isReleased ? t - apexTime : 0;
  const dropHeight = isReleased ? apexHeight - (gravity * dropTime * dropTime) / 2 : apexHeight;
  const dropVelocity = isReleased ? -gravity * dropTime : 0;
  const dropAcceleration = isReleased ? -gravity : 0;

  const heightScale = 120;
  const baseY = 320;

  function toScreenY(h) {
    return baseY - h * heightScale;
  }

  const tossX = 200;
  const dropX = 440;

  const tossY = toScreenY(tossHeight);
  const dropY = toScreenY(dropHeight);

  let tossState = "Rising";
  if (t < 0.05) tossState = "At launch";
  else if (Math.abs(t - apexTime) < 0.05) tossState = "At the top";
  else if (t > apexTime && tossHeight > 0) tossState = "Falling";
  else if (tossHeight <= 0) tossState = "At launch height";

  let dropState = "Held in place";
  if (t > apexTime && t < apexTime + 0.05) dropState = "Just released";
  else if (t >= apexTime + 0.05 && dropHeight > 0) dropState = "Falling together";
  else if (dropHeight <= 0 && t >= apexTime) dropState = "At launch height";

  const objects = [];

  objects.push(...sdk.panel({ x: 60, y: 50, w: 240, h: 320, title: "Toss lane", state: tossState, id: "lane.toss" }));
  objects.push(...sdk.panel({ x: 340, y: 50, w: 240, h: 320, title: "Drop lane", state: dropState, id: "lane.drop" }));

  objects.push(sdk.axis("axis.toss", { x: 100, y: 320, length: 260, orientation: "y", min: 0, max: 2.2, label: "Height", unit: "m" }));
  objects.push(sdk.axis("axis.drop", { x: 380, y: 320, length: 260, orientation: "y", min: 0, max: 2.2, label: "Height", unit: "m" }));

  objects.push(sdk.circle("ball.toss", tossX, tossY, 28, { role: "output" }));
  objects.push(sdk.circle("ball.drop", dropX, dropY, 28, { role: "output" }));

  objects.push(sdk.vector("vec.v.toss", { x: tossX - 16, y: tossY }, { value: tossVelocity, direction: "up" }, { scale: 15, label: "v" }));
  objects.push(sdk.vector("vec.a.toss", { x: tossX + 16, y: tossY }, { value: tossAcceleration, direction: "up" }, { scale: 8, label: "a" }));

  objects.push(sdk.vector("vec.v.drop", { x: dropX - 16, y: dropY }, { value: dropVelocity, direction: "up" }, { scale: 15, label: "v" }));
  objects.push(sdk.vector("vec.a.drop", { x: dropX + 16, y: dropY }, { value: dropAcceleration, direction: "up" }, { scale: 8, label: "a" }));

  objects.push(...sdk.callout(tossX + 45, tossY - 20, [
    `v: ${sdk.format(tossVelocity, 2)} m/s`,
    `a: ${sdk.format(tossAcceleration, 1)} m/s^2`
  ], { id: "callout.toss" }));

  objects.push(...sdk.callout(dropX + 45, dropY - 20, [
    `v: ${sdk.format(dropVelocity, 2)} m/s`,
    `a: ${sdk.format(dropAcceleration, 1)} m/s^2`
  ], { id: "callout.drop" }));

  objects.push(sdk.gate("gate", dropX, toScreenY(apexHeight), { open: isReleased, label: "Apex Gate" }));

  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts: [
        { id: "tossedVelocity", value: tossVelocity },
        { id: "tossedAcceleration", value: tossAcceleration },
        { id: "dropVelocity", value: dropVelocity },
        { id: "dropAcceleration", value: dropAcceleration }
      ]
    },
    quantities: {
      launchSpeed,
      gravity,
      apexTime,
      apexHeight,
      tossedVelocity: tossVelocity,
      tossedAcceleration: tossAcceleration,
      tossedHeight: tossHeight,
      dropVelocity,
      dropAcceleration,
      dropHeight
    }
  };
}
